/** Real signed local scope and actual core plan/intent/job repositories. */
final class OrderHeldJobWorkflowTest extends WP_UnitTestCase {
 use NativeBusinessOrderFixture;
 private array $heldJobSnapshots=[];
 private int $httpCalls=0;
 private $denyHttp;
 public function setUp():void {parent::setUp();\DigiForge\Core\Activator::activate();global $wpdb;foreach([Tables::jobs(),Tables::fulfillment_intents()]as $table)$this->heldJobSnapshots[$table]=$wpdb->get_results('SELECT * FROM '.$table,ARRAY_A);$this->bootOrderFixture();$this->denyHttp=function(){$this->httpCalls++;return new WP_Error('unexpected_http');};add_filter('pre_http_request',$this->denyHttp);}
 public function tearDown():void {remove_filter('pre_http_request',$this->denyHttp);try{global $wpdb;$wpdb->query('ROLLBACK');foreach($this->heldJobSnapshots as $table=>$rows){$wpdb->query('DELETE FROM '.$table);foreach($rows as $row)$wpdb->insert($table,$row,array_fill(0,count($row),'%s'));}$this->restoreOrderFixture();self::assertSame(0,$this->httpCalls);}finally{parent::tearDown();}}
 public function testActualRegisteredTwoStepEnqueueCreatesOnlyBlockedMetadataAndScopedInspection():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class),'The connected scoped held-job operator workflow is missing.');[$order,$intent]=$this->held();self::assertNotFalse(has_action('admin_post_'.OrderHeldJobWorkflow::ENQUEUE));
  $body=$this->body(OrderHeldJobWorkflow::ENQUEUE,$order,$intent);$preview=$this->invoke($body);self::assertStringContainsString('Confirm BLOCKED held-job metadata',$preview);$confirm=$this->confirmed($body,$preview);$html=$this->invoke($confirm);self::assertStringContainsString('BLOCKED held-job metadata recorded',$html);self::assertStringContainsString('df_intent_id='.$intent,$html);
  global $wpdb;$job=$wpdb->get_row("SELECT * FROM ".Tables::jobs()." WHERE job_type='shop2_held_preparation' ORDER BY id DESC LIMIT 1",ARRAY_A);self::assertSame('BLOCKED',$job['state']);self::assertSame('0',$job['attempts']);self::assertNull($job['locked_by']);self::assertNull($job['lease_expires_at']);$payload=json_decode($job['payload'],true);self::assertSame($order,$payload['order_id']);self::assertSame($intent,$payload['intent_id']);self::assertSame(get_current_user_id(),$payload['actor_id']);self::assertSame('BLOCKED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::fulfillment_intents().' WHERE id=%d',$intent)));
  ob_start();(new OrderHeldJobWorkflow())->render('personalized_pod',$order,$intent);$panel=(string)ob_get_clean();self::assertStringContainsString('Held job #'.$job['id'],$panel);self::assertStringNotContainsString('name="payload"',$panel);self::assertStringNotContainsString('Dispatch job',$panel);self::assertStringNotContainsString('Retry job',$panel);self::assertTrue(Settings::safety_locked());$this->invoke($confirm);self::assertSame('1',$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".Tables::jobs()." WHERE job_type='shop2_held_preparation' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.intent_id'))=%s",(string)$intent)));
 }
 public function testActualExpiredLeaseQuarantineIsPurposeBoundAndNeverRequeuesOrDispatches():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$job=$this->expiredJob($order,$intent);$body=$this->body(OrderHeldJobWorkflow::QUARANTINE,$order,$intent,$job);$preview=$this->invoke($body);self::assertStringContainsString('Confirm expired held-job quarantine',$preview);self::assertStringContainsString('HUMAN_REVIEW',$preview);$confirm=$this->confirmed($body,$preview);self::assertStringContainsString('Expired held job moved to HUMAN_REVIEW',$this->invoke($confirm));
  global $wpdb;$row=$wpdb->get_row($wpdb->prepare('SELECT * FROM '.Tables::jobs().' WHERE id=%d',$job),ARRAY_A);self::assertSame('HUMAN_REVIEW',$row['state']);self::assertSame('0',$row['attempts']);self::assertSame('LEASE_EXPIRED',$row['last_error']);self::assertNull($row['locked_by']);self::assertNull($row['lease_expires_at']);self::assertStringNotContainsString('Expired held job moved to HUMAN_REVIEW',$this->invoke($confirm));self::assertTrue(Settings::safety_locked());
 }
 public function testChangedSourceWrongTupleShopActorAndNonceCannotEnqueue():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent,,$line]=$this->held();$body=$this->body(OrderHeldJobWorkflow::ENQUEUE,$order,$intent);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$wpdb->update(Tables::order_line_items(),['quantity'=>3],['id'=>$line]);self::assertStringNotContainsString('BLOCKED held-job metadata recorded',$this->invoke($confirm));$wpdb->update(Tables::order_line_items(),['quantity'=>2],['id'=>$line]);
  $wrong=$body;$wrong['shop_key']='digital';self::assertStringNotContainsString('Confirm BLOCKED held-job metadata',$this->invoke($wrong));$wrong=$body;$wrong['intent_id']=(string)($intent+1);self::assertStringContainsString('nonce',$this->invoke($wrong));$wrong=$body;$wrong['_wpnonce']='invalid';self::assertStringContainsString('nonce',$this->invoke($wrong));wp_set_current_user(0);self::assertStringNotContainsString('BLOCKED held-job metadata recorded',$this->invoke($confirm));self::assertSame('0',$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM ".Tables::jobs()." WHERE job_type='shop2_held_preparation' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.intent_id'))=%s",(string)$intent)));
 }
 public function testChangedLeaseAndForeignJobCannotBeQuarantinedFromOldPreview():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$job=$this->expiredJob($order,$intent);$body=$this->body(OrderHeldJobWorkflow::QUARANTINE,$order,$intent,$job);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$wpdb->update(Tables::jobs(),['locked_by'=>'different-local-owner','lease_expires_at'=>gmdate('Y-m-d H:i:s',time()+300)],['id'=>$job]);self::assertStringNotContainsString('Expired held job moved to HUMAN_REVIEW',$this->invoke($confirm));self::assertSame('RUNNING',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::jobs().' WHERE id=%d',$job)));
  [$otherOrder,$otherIntent]=$this->held();$foreign=$this->expiredJob($otherOrder,$otherIntent);$wrong=$this->body(OrderHeldJobWorkflow::QUARANTINE,$order,$intent,$foreign);self::assertStringNotContainsString('Confirm expired held-job quarantine',$this->invoke($wrong));
 }
 public function testFailedQueueWriteConsumesConfirmationAndGetNeverWrites():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$body=$this->body(OrderHeldJobWorkflow::ENQUEUE,$order,$intent);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$deny=static fn(string $sql):string=>preg_match('/^INSERT INTO `?'.preg_quote(Tables::jobs(),'/').'`?/i',$sql)?'INSERT INTO missing_held_operator_job (id) VALUES (1)':$sql;$prior=$wpdb->suppress_errors(true);add_filter('query',$deny);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$deny);$wpdb->suppress_errors($prior);}self::assertStringNotContainsString('BLOCKED held-job metadata recorded',$html);self::assertStringContainsString('already been accepted',$this->invoke($confirm));
  self::assertStringContainsString('POST required',$this->invoke($body,'GET'));self::assertTrue(Settings::safety_locked());
 }
 public function testMountedQuarantineRemainsReachableAfterRealConnectionReviewRevocation():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$job=$this->expiredJob($order,$intent);$connection=new \DigiForge\POD\ScopedProviderConnection();$current=$connection->status('personalized_pod',$this->fixture->integration,'printify.connection.read');PortalAccessFixture::login($this->fixture->reviewer);PrintifyApiApprovalFixture::checked($connection->decide('personalized_pod',$this->fixture->integration,'printify.connection.read',$current['review_revision'],$current['binding_hash'],'REVOKED',wp_generate_uuid4()));$this->fixture->owner();self::assertWPError((new \DigiForge\Orders\HeldFulfillmentPreparation())->forOrder('personalized_pod',$order));
  $get=$_GET;try{$_GET=['df_order_id'=>(string)$order,'df_intent_id'=>(string)$intent,'df_held_job_id'=>(string)$job];ob_start();(new \DigiForge\Portal\OrderHeldPreparationPanel())->render('personalized_pod');$html=(string)ob_get_clean();self::assertStringContainsString('Held job #'.$job,$html);self::assertStringContainsString('Preview expired held-job quarantine',$html);ob_start();(new \DigiForge\Portal\OrderHeldPreparationPanel())->render('digital');$foreign=(string)ob_get_clean();self::assertStringNotContainsString('Held job #'.$job,$foreign);$actor=wp_get_current_user();$actor->add_cap('manage_digiforge_automation',false);try{ob_start();(new \DigiForge\Portal\OrderHeldPreparationPanel())->render('personalized_pod');$denied=(string)ob_get_clean();self::assertStringNotContainsString('Held job #'.$job,$denied);}finally{$actor->add_cap('manage_digiforge_automation');}}finally{$_GET=$get;}
 }
 public function testMixedPostAcknowledgementLeaseSnapshotsCannotBorrowAnotherConfirmation():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$job=$this->expiredJob($order,$intent);$body=$this->body(OrderHeldJobWorkflow::QUARANTINE,$order,$intent,$job);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$accepted=false;$reads=0;$swapped=false;$restored=false;
  $race=static function(string $sql)use($wpdb,$job,&$accepted,&$reads,&$swapped,&$restored):string{if(str_starts_with($sql,'INSERT INTO `'.Tables::audit_log().'`')&&str_contains($sql,'portal_review_confirmation_accepted'))$accepted=true;if($accepted&&str_starts_with($sql,'SELECT * FROM '.Tables::jobs().' WHERE id='.$job)){++$reads;if($reads===1||$reads===5){$wpdb->update(Tables::jobs(),['locked_by'=>'different-expired-owner'],['id'=>$job]);$swapped=true;}if($reads===3){$wpdb->update(Tables::jobs(),['locked_by'=>'synthetic-held-owner'],['id'=>$job]);$restored=true;}}return $sql;};add_filter('query',$race);try{$html=$this->invoke($confirm);}finally{remove_filter('query',$race);}self::assertTrue($accepted);self::assertTrue($swapped);self::assertTrue($restored);self::assertStringNotContainsString('Expired held job moved to HUMAN_REVIEW',$html);self::assertSame('RUNNING',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::jobs().' WHERE id=%d',$job)));
 }
 public function testRenderDoesNotEmitPreviouslyReadJobMetadataAfterFinalModuleRevocation():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$job=$this->expiredJob($order,$intent);$actor=wp_get_current_user();$reads=0;$revoked=false;$get=$_GET;
  $race=static function(string $sql)use($job,$actor,&$reads,&$revoked):string{if(str_starts_with($sql,'SELECT * FROM '.Tables::jobs().' WHERE id='.$job)&&++$reads===4){$actor->add_cap('manage_digiforge_automation',false);$revoked=true;}return $sql;};$_GET=['df_held_job_id'=>(string)$job];add_filter('query',$race);ob_start();try{(new OrderHeldJobWorkflow())->render('personalized_pod',$order,$intent);$html=(string)ob_get_contents();}finally{ob_end_clean();remove_filter('query',$race);$actor->add_cap('manage_digiforge_automation');$_GET=$get;}self::assertTrue($revoked);self::assertStringNotContainsString('Held job #'.$job,$html);self::assertStringNotContainsString('Preview expired held-job quarantine',$html);
 }
 public function testOuterTransactionIsDeniedBeforeAcknowledgementAndDoesNotCommitCallerState():void {
  self::assertTrue(class_exists(OrderHeldJobWorkflow::class));[$order,$intent]=$this->held();$body=$this->body(OrderHeldJobWorkflow::ENQUEUE,$order,$intent);$confirm=$this->confirmed($body,$this->invoke($body));global $wpdb;$before=$wpdb->get_var("SELECT COUNT(*) FROM ".Tables::audit_log()." WHERE event_type='portal_review_confirmation_accepted'");$wpdb->query('START TRANSACTION');try{$html=$this->invoke($confirm);self::assertStringContainsString('clean database transaction boundary',$html);self::assertSame('1',(string)$wpdb->get_var('SELECT @@session.in_transaction'));self::assertSame($before,$wpdb->get_var("SELECT COUNT(*) FROM ".Tables::audit_log()." WHERE event_type='portal_review_confirmation_accepted'"));}finally{$wpdb->query('ROLLBACK');}
 }
 private function body(string $action,int $order,int $intent,int $job=0):array {$tuple=$action.':'.$order.':'.$intent.($job>0?':'.$job:'');$body=['action'=>$action,'shop_key'=>'personalized_pod','order_id'=>(string)$order,'intent_id'=>(string)$intent,'phase'=>'preview','_wpnonce'=>wp_create_nonce($tuple),'return_url'=>home_url('/operations/')];if($job>0)$body['job_id']=(string)$job;return $body;}
 private function invoke(array $body,string $method='POST'):string {$post=$_POST;$hadMethod=array_key_exists('REQUEST_METHOD',$_SERVER);$priorMethod=$_SERVER['REQUEST_METHOD']??null;$_POST=$body;$_SERVER['REQUEST_METHOD']=$method;ob_start();try{try{do_action('admin_post_'.$body['action']);}catch(WPDieException $error){echo esc_html($error->getMessage());}return (string)ob_get_contents();}finally{ob_end_clean();$_POST=$post;if($hadMethod)$_SERVER['REQUEST_METHOD']=$priorMethod;else unset($_SERVER['REQUEST_METHOD']);}}
 private function confirmed(array $body,string $html):array {$dom=new DOMDocument();@$dom->loadHTML($html);foreach($dom->getElementsByTagName('input')as $input){$key=$input->getAttribute('name');if($key==='df_confirmation_tokens[REVIEW]')$body['df_confirmation_tokens']['REVIEW']=$input->getAttribute('value');elseif(str_starts_with($key,'df_confirmation_'))$body[$key]=$input->getAttribute('value');}$body['phase']='confirm';$body['df_confirm_review']='1';return $body;}
 private function expiredJob(int $order,int $intent):int {$job=PrintifyApiApprovalFixture::checked((new Shop2HeldPreparationDispatcher())->enqueue('personalized_pod',$order,$intent,wp_generate_uuid4()));self::assertIsInt($job);$repo=new JobRepository();self::assertTrue($repo->transition($job,'BLOCKED','QUEUED'));self::assertTrue($repo->acquireLease($job,'synthetic-held-owner',60));self::assertTrue($repo->start($job,'synthetic-held-owner'));global $wpdb;self::assertSame(1,$wpdb->update(Tables::jobs(),['locked_at'=>gmdate('Y-m-d H:i:s',time()-300),'lease_expires_at'=>gmdate('Y-m-d H:i:s',time()-120)],['id'=>$job]));return $job;}
 private function held():array {[, $mapping,$version]=$this->product();$repo=new Repository();$order=PrintifyApiApprovalFixture::checked($repo->createOrder(['channel'=>'etsy','shop_reference'=>'personalized_pod','environment'=>'test','currency'=>'USD','personalization_required'=>true]));$line=PrintifyApiApprovalFixture::checked($repo->addLineItem(['order_id'=>$order['id'],'product_version_id'=>$version,'provider_mapping_id'=>$mapping,'quantity'=>2]));$pod=new \DigiForge\POD\Repository();$schema=PrintifyApiApprovalFixture::checked($pod->createPersonalizationSchema(['product_version_id'=>$version,'schema_key'=>'held-job-local','version_label'=>'v1','field_definitions'=>[['key'=>'name','type'=>'text','required'=>true]]]));foreach(['VALIDATED','REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($pod->transition('personalization',(int)$schema['id'],$state));$submission=PrintifyApiApprovalFixture::checked($repo->createPersonalization(['order_line_item_id'=>$line['id'],'personalization_schema_id'=>$schema['id'],'payload'=>['name'=>'Synthetic buyer']]));PrintifyApiApprovalFixture::checked($repo->reviewPersonalization((int)$submission['id'],'APPROVED'));foreach(['REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($repo->transition('order',(int)$order['id'],$state));$plan=PrintifyApiApprovalFixture::checked($repo->createPlan(['order_id'=>$order['id'],'provider'=>'printify','shipping_method_metadata'=>['method'=>'standard'],'cost_snapshot_metadata'=>['base_production_cost'=>10,'shipping_estimate'=>4,'currency'=>'USD']]));foreach(['REVIEW_REQUIRED','APPROVED']as $state)PrintifyApiApprovalFixture::checked($repo->transition('plan',(int)$plan['id'],$state));$intent=PrintifyApiApprovalFixture::checked($repo->createIntent(['order_id'=>$order['id'],'fulfillment_plan_id'=>$plan['id'],'intent_type'=>'PREPARE_FULFILLMENT']));Settings::protectProduction();return [(int)$order['id'],(int)$intent['id'],(int)$plan['id'],(int)$line['id']];}
}
